import zlib
import json

class LogEntry:
    def __init__(self, index: int, term: int, payload: dict, checksum: int = 0):
        self.index = index
        self.term = term
        self.payload = payload
        self.checksum = checksum if checksum != 0 else self.compute_checksum()

    def compute_checksum(self) -> int:
        header = f"{self.index}:{self.term}".encode('utf-8')
        return zlib.crc32(header)

    def is_valid(self) -> bool:
        return self.checksum == self.compute_checksum()

    def to_dict(self) -> dict:
        return {
            "index": self.index,
            "term": self.term,
            "payload": self.payload,
            "checksum": self.checksum,
        }

