from wal_fsm.entry import LogEntry
from wal_fsm.log_storage import WalLogStorage
from wal_fsm.state_machine import StateMachine
from typing import List, Dict


class DistributedWalNode:
    def __init__(self, node_id: str, peers: List[str]):
        self.node_id = node_id
        self.peers = peers
        self.wal = WalLogStorage()
        self.fsm = StateMachine()
        self.commit_index = 0
        self.uncommitted_votes: Dict[int, set] = {}

    def propose_entry(self, term: int, payload: dict) -> LogEntry:
        idx = self.wal.size() + 1
        entry = LogEntry(index=idx, term=term, payload=payload)
        self.wal.append(entry)
        self.uncommitted_votes[idx] = {self.node_id}
        return entry

    def record_peer_vote(self, index: int, peer_id: str) -> bool:
        if index not in self.uncommitted_votes:
            self.uncommitted_votes[index] = set()
        self.uncommitted_votes[index].add(peer_id)

        total_cluster_size = len(self.peers) + 1
        votes_count = len(self.uncommitted_votes[index])

        if votes_count >= total_cluster_size:
            entry = self.wal.get(index)
            if entry:
                self.fsm.apply(entry.index, entry.payload)
                self.commit_index = index
                return True
        return False


