from typing import Dict, Any


class StateMachine:
    def __init__(self):
        self.kv_store: Dict[str, Any] = {}
        self.last_applied_index: int = 0

    def apply(self, index: int, command: dict) -> Any:
        op = command.get("op")
        key = command.get("key")
        val = command.get("val")

        if op == "SET":
            self.kv_store[key] = val
        elif op == "DEL":
            self.kv_store.pop(key, None)

        self.last_applied_index = index
        return self.kv_store.get(key)

    def get(self, key: str) -> Any:
        return self.kv_store.get(key)

    def snapshot(self) -> dict:
        return {
            "kv_store": self.kv_store.copy(),
            "last_applied_index": self.last_applied_index,
        }

    def apply_snapshot(self, snapshot_data: dict) -> None:
        self.kv_store = snapshot_data.get("kv_store", {}).copy()


